async function fetchUserData(userId) {
  try {
    const response = await fetch(`https://api.example.com/users/${userId}`);

    // Check if HTTP response status indicates an error
    if (!response.ok) {
      throw new Error(`HTTP Error: ${response.status}`);
    }

    // Parse and return the JSON data
    const data = await response.json();
    return data;

  } catch (error) {
    // Handle network errors, HTTP errors, and JSON parsing errors
    if (error instanceof TypeError) {
      console.error('Network error: Unable to reach the API', error.message);
    } else if (error instanceof SyntaxError) {
      console.error('Invalid JSON response from server', error.message);
