## Solution

```python
import heapq
from collections import defaultdict

class HuffmanNode:
    def __init__(self, freq, char=None, left=None, right=None):
        self.freq = freq
        self.char = char
        self.left = left
        self.right = right

    def __lt__(self, other):
        return self.freq < other.freq

def build_huffman_tree(frequencies):
    """Build Huffman tree from frequency dictionary."""
    if not frequencies:
        return None

    heap = [HuffmanNode(freq, char) for char, freq in frequencies.items()]
    heapq.heapify(heap)

    while len(heap) > 1:
        left = heapq.heappop(heap)
        right = heapq.heappop(heap)
        parent = HuffmanNode(left.freq + right.freq, left=left, right=right)
        heapq.heappush(heap, parent)

    return heap[0] if heap else None

def decode_adaptive_huffman(encoded_bits, initial_frequencies):
    frequencies = dict(initial_frequencies)
    decoded = []
    bit_index = 0

    while bit_index < len(encoded_bits):
        tree = build_huffman_tree(frequencies)
        if tree is None:
            break

        # Traverse tree to find next symbol
        node = tree
        while node.char is None and bit_index < len(encoded_bits):
            if encoded_bits[bit_index] == '0':
                node = node.left if node.left else node
            else:
                node = node.right if node.right else node
            bit_index += 1

        if node.char:
            decoded.append(node.char)
            frequencies[node.char] = frequencies.get(node.char, 0) + 1

    return ''.join(decoded)
```

The solution builds a fresh Huffman tree after decoding each character, using the updated frequencies. This implements the adaptive behavior where the tree evolves as we decode more symbols.

