## Problem

A hybrid recommender system combines collaborative filtering scores with content-based scores using a weighted average. Trace through the following code and determine the final recommendation score for User 2 and Item C.

```python
class HybridRecommender:
    def __init__(self, cf_weight=0.6, cb_weight=0.4):
        self.cf_weight = cf_weight
        self.cb_weight = cb_weight
        self.cf_scores = {
            'User1': {'ItemA': 0.8, 'ItemB': 0.5, 'ItemC': 0.3},
            'User2': {'ItemA': 0.7, 'ItemB': 0.6, 'ItemC': 0.4}
        }
        self.cb_scores = {
            'User1': {'ItemA': 0.9, 'ItemB': 0.4, 'ItemC': 0.7},
            'User2': {'ItemA': 0.6, 'ItemB': 0.8, 'ItemC': 0.5}
        }

    def compute_hybrid_score(self, user, item):
        cf_score = self.cf_scores[user][item]
        cb_score = self.cb_scores[user][item]
        hybrid = (self.cf_weight * cf_score) + (self.cb_weight * cb_score)
        return round(hybrid, 3)

    def rank_items(self, user):
        scores = {}
        for item in ['ItemA', 'ItemB', 'ItemC']:
            scores[item] = self.compute_hybrid_score(user, item)
        return sorted(scores.items(), key=lambda x: x[1], reverse=True)

recommender = HybridRecommender(cf_weight=0.6, cb_weight=0.4)
result = recommender.rank_items('User2')
print(result)
```

