```python
def deploy_application(environment, version, skip_tests=False):
    stages = ["build", "test", "deploy"]
    results = {}

    if environment not in ["staging", "production"]:
        return {"status": "error", "message": "Invalid environment"}

    for stage in stages:
        if skip_tests and stage == "test":
            results[stage] = "skipped"
            continue

        results[stage] = execute_stage(stage, version, environment)

        if results[stage] == "failed":
            rollback_deployment(environment, version)
            return {"status": "failed", "failed_stage": stage, "logs": results}

    return {"status": "success", "version": version, "environment": environment}

def execute_stage(stage, version, environment):
    print(f"Executing {stage} for version {version} in {environment}")
    # Simulated execution
    if stage == "build" and version == "1.0.0":
        return "success"
    elif stage == "test" and environment == "production":
        return "failed"
    elif stage == "deploy":
        return "success"
    return "success"

def rollback_deployment(environment, version):
    print(f"Rolling back {version} from {environment}")
```

**Question:** If `deploy_application("production", "1.0.0", skip_tests=False)` is called, what will be the final return value? Trace through the execution step by step and explain why.
